
/*
=========================================================
 PROJECT : AECU V2.0
 MODULE  : Real-Time Embedded Control Unit
 MCU     : STM32F401RE
 RTOS    : FreeRTOS
 LANGUAGE: Embedded C

 FEATURES:
 - Multi-task architecture
 - ADC sensor acquisition
 - PID fan control
 - CAN communication
 - Fault management
 - Telemetry
=========================================================
*/

#include "main.h"

#include "FreeRTOS.h"
#include "task.h"
#include "queue.h"

#include <stdint.h>
#include <stdbool.h>

/* Peripheral handles generated by CubeMX */

extern ADC_HandleTypeDef hadc1;
extern TIM_HandleTypeDef htim3;
extern CAN_HandleTypeDef hcan1;

/* SYSTEM CONFIGURATION */

#define SAMPLE_PERIOD_MS      10
#define CAN_PERIOD_MS         50

#define TARGET_TEMP_DEFAULT   65.0f
#define MAX_TEMP              85.0f

#define PWM_MAX               100.0f

/* SYSTEM STATES */

typedef enum {
    SYSTEM_INIT = 0,
    SYSTEM_RUNNING,
    SYSTEM_WARNING,
    SYSTEM_SAFE_MODE
} SystemState;

typedef enum {
    FAULT_NONE = 0,
    FAULT_SENSOR,
    FAULT_OVERTEMP,
    FAULT_VOLTAGE
} FaultCode;

/* DATA STRUCTURES */

typedef struct {
    float temperature;
    float voltage;
    bool valid;
} SensorData;

typedef struct {
    float temperature;
    float target;
    float voltage;
    uint8_t pwm;
    SystemState state;
    FaultCode fault;
} TelemetryData;

/* RTOS QUEUES */

static QueueHandle_t sensorQueue;
static QueueHandle_t telemetryQueue;

/* SYSTEM VARIABLES */

static volatile float targetTemperature =
    TARGET_TEMP_DEFAULT;

static SystemState systemState = SYSTEM_INIT;

static FaultCode activeFault = FAULT_NONE;

/* PID PARAMETERS */

static float Kp = 3.0f;
static float Ki = 0.5f;
static float Kd = 0.1f;

static float integral = 0.0f;
static float previousError = 0.0f;

/* PID CONTROLLER */

static float PID_Compute(float target,
                         float actual,
                         float dt)
{
    float error = actual - target;

    integral += error * dt;

    if (integral > 100.0f)
        integral = 100.0f;

    if (integral < -100.0f)
        integral = -100.0f;

    float derivative =
        (error - previousError) / dt;

    previousError = error;

    float output =
        Kp * error +
        Ki * integral +
        Kd * derivative;

    if (output > PWM_MAX)
        output = PWM_MAX;

    if (output < 0.0f)
        output = 0.0f;

    return output;
}

/* SENSOR MANAGER */

static SensorData Sensor_Read(void)
{
    SensorData data = {0};

    if (HAL_ADC_Start(&hadc1) != HAL_OK)
        return data;

    if (HAL_ADC_PollForConversion(
            &hadc1, 5) != HAL_OK)
    {
        HAL_ADC_Stop(&hadc1);
        return data;
    }

    uint32_t adcValue =
        HAL_ADC_GetValue(&hadc1);

    HAL_ADC_Stop(&hadc1);

    float voltage =
        (adcValue * 3.3f) / 4095.0f;

    data.temperature =
        voltage * 100.0f;

    data.voltage = voltage;

    data.valid = true;

    return data;
}

/* FAULT MANAGER */

static FaultCode Fault_Check(SensorData data)
{
    if (!data.valid)
        return FAULT_SENSOR;

    if (data.temperature < -10.0f ||
        data.temperature > 150.0f)
        return FAULT_SENSOR;

    if (data.temperature > MAX_TEMP)
        return FAULT_OVERTEMP;

    if (data.voltage < 0.0f ||
        data.voltage > 3.3f)
        return FAULT_VOLTAGE;

    return FAULT_NONE;
}

/* SAFETY MANAGER */

static void Safety_Update(FaultCode fault)
{
    activeFault = fault;

    if (fault != FAULT_NONE)
    {
        systemState = SYSTEM_SAFE_MODE;
    }
    else
    {
        systemState = SYSTEM_RUNNING;
    }
}

/* PWM MOTOR / FAN CONTROL */

static void Fan_SetPWM(float percentage)
{
    if (percentage > 100.0f)
        percentage = 100.0f;

    if (percentage < 0.0f)
        percentage = 0.0f;

    uint32_t arr =
        __HAL_TIM_GET_AUTORELOAD(&htim3);

    uint32_t compare =
        (uint32_t)((percentage / 100.0f)
                   * arr);

    __HAL_TIM_SET_COMPARE(
        &htim3,
        TIM_CHANNEL_1,
        compare
    );
}

/* TASK 1: SENSOR ACQUISITION */

static void SensorTask(void *argument)
{
    TickType_t lastWakeTime =
        xTaskGetTickCount();

    for (;;)
    {
        SensorData data = Sensor_Read();

        xQueueOverwrite(sensorQueue, &data);

        vTaskDelayUntil(
            &lastWakeTime,
            pdMS_TO_TICKS(SAMPLE_PERIOD_MS)
        );
    }
}

/* TASK 2: CONTROL SYSTEM */

static void ControlTask(void *argument)
{
    SensorData sensor;

    TelemetryData telemetry = {0};

    for (;;)
    {
        if (xQueueReceive(
                sensorQueue,
                &sensor,
                portMAX_DELAY) == pdPASS)
        {
            FaultCode fault =
                Fault_Check(sensor);

            Safety_Update(fault);

            float target;

            taskENTER_CRITICAL();
            target = targetTemperature;
            taskEXIT_CRITICAL();

            float pwm = 0.0f;

            if (systemState == SYSTEM_RUNNING)
            {
                pwm = PID_Compute(
                    target,
                    sensor.temperature,
                    0.01f
                );
            }
            else
            {
                // Fail-safe fan command
                // Sensor / thermal fault:
                // request maximum cooling.
                pwm = 100.0f;

                integral = 0.0f;
                previousError = 0.0f;
            }

            Fan_SetPWM(pwm);

            telemetry.temperature =
                sensor.temperature;

            telemetry.voltage =
                sensor.voltage;

            telemetry.target = target;

            telemetry.pwm = (uint8_t)pwm;

            telemetry.state = systemState;

            telemetry.fault = activeFault;

            xQueueOverwrite(
                telemetryQueue,
                &telemetry
            );
        }
    }
}

/* TASK 3: CAN TRANSMISSION */

static void CAN_SendTelemetry(
    TelemetryData data)
{
    CAN_TxHeaderTypeDef txHeader = {0};

    uint8_t txData[8] = {0};

    uint32_t mailbox;

    int16_t temp =
        (int16_t)(data.temperature * 100.0f);

    uint16_t voltage =
        (uint16_t)(data.voltage * 1000.0f);

    uint16_t target =
        (uint16_t)(data.target * 100.0f);

    txHeader.StdId = 0x100;
    txHeader.IDE = CAN_ID_STD;
    txHeader.RTR = CAN_RTR_DATA;
    txHeader.DLC = 8;
    txHeader.TransmitGlobalTime = DISABLE;

    txData[0] = (uint8_t)(temp & 0xFF);
    txData[1] = (uint8_t)((temp >> 8) & 0xFF);

    txData[2] = (uint8_t)(voltage & 0xFF);
    txData[3] = (uint8_t)((voltage >> 8) & 0xFF);

    txData[4] = data.pwm;
    txData[5] = (uint8_t)data.state;

    txData[6] = (uint8_t)(target & 0xFF);
    txData[7] = (uint8_t)((target >> 8) & 0xFF);

    HAL_CAN_AddTxMessage(
        &hcan1,
        &txHeader,
        txData,
        &mailbox
    );
}

static void CanTxTask(void *argument)
{
    TelemetryData data;

    for (;;)
    {
        if (xQueuePeek(
                telemetryQueue,
                &data,
                pdMS_TO_TICKS(CAN_PERIOD_MS))
            == pdPASS)
        {
            CAN_SendTelemetry(data);
        }

        vTaskDelay(pdMS_TO_TICKS(CAN_PERIOD_MS));
    }
}

/* TASK 4: CAN COMMAND RECEIVER */

static void CanRxTask(void *argument)
{
    CAN_RxHeaderTypeDef rxHeader;

    uint8_t rxData[8];

    for (;;)
    {
        if (HAL_CAN_GetRxFifoFillLevel(
                &hcan1,
                CAN_RX_FIFO0) > 0)
        {
            if (HAL_CAN_GetRxMessage(
                    &hcan1,
                    CAN_RX_FIFO0,
                    &rxHeader,
                    rxData) == HAL_OK)
            {
                if (rxHeader.IDE == CAN_ID_STD &&
                    rxHeader.StdId == 0x200 &&
                    rxHeader.DLC >= 2)
                {
                    uint16_t rawTarget =
                        (uint16_t)rxData[0] |
                        ((uint16_t)rxData[1] << 8);

                    float newTarget =
                        rawTarget / 100.0f;

                    if (newTarget >= 20.0f &&
                        newTarget <= 80.0f)
                    {
                        taskENTER_CRITICAL();

                        targetTemperature =
                            newTarget;

                        taskEXIT_CRITICAL();
                    }
                }
            }
        }

        vTaskDelay(pdMS_TO_TICKS(2));
    }
}

/* CAN INITIALIZATION */

static HAL_StatusTypeDef CAN_Configure(void)
{
    CAN_FilterTypeDef filter = {0};

    filter.FilterBank = 0;
    filter.FilterMode = CAN_FILTERMODE_IDMASK;
    filter.FilterScale = CAN_FILTERSCALE_32BIT;

    filter.FilterIdHigh = 0;
    filter.FilterIdLow = 0;

    filter.FilterMaskIdHigh = 0;
    filter.FilterMaskIdLow = 0;

    filter.FilterFIFOAssignment = CAN_FILTER_FIFO0;
    filter.FilterActivation = ENABLE;
    filter.SlaveStartFilterBank = 14;

    if (HAL_CAN_ConfigFilter(
            &hcan1, &filter) != HAL_OK)
        return HAL_ERROR;

    return HAL_CAN_Start(&hcan1);
}

/* APPLICATION ENTRY */

void AECU_Start(void)
{
    sensorQueue = xQueueCreate(
        1,
        sizeof(SensorData)
    );

    telemetryQueue = xQueueCreate(
        1,
        sizeof(TelemetryData)
    );

    if (sensorQueue == NULL ||
        telemetryQueue == NULL)
    {
        Error_Handler();
    }

    if (HAL_TIM_PWM_Start(
            &htim3,
            TIM_CHANNEL_1) != HAL_OK)
    {
        Error_Handler();
    }

    if (CAN_Configure() != HAL_OK)
    {
        Error_Handler();
    }

    Fan_SetPWM(0.0f);

    xTaskCreate(
        SensorTask,
        "SensorTask",
        256,
        NULL,
        3,
        NULL
    );

    xTaskCreate(
        ControlTask,
        "ControlTask",
        256,
        NULL,
        4,
        NULL
    );

    xTaskCreate(
        CanTxTask,
        "CanTxTask",
        256,
        NULL,
        2,
        NULL
    );

    xTaskCreate(
        CanRxTask,
        "CanRxTask",
        256,
        NULL,
        2,
        NULL
    );

    vTaskStartScheduler();

    Error_Handler();
}
